```c
#include <stdlib.h>
#include <string.h>
#include <math.h>

// auction algorithm for min-cost assignment
// returns assignment: assign[i] = j (column assigned to row i)
void auction(int n, const double* cost, int* assign) {
    double* price = calloc(n, sizeof(double));
    int* owner = malloc(n * sizeof(int)); // owner[j] = row assigned to col j, -1 if none
    for (int j = 0; j < n; j++) owner[j] = -1;

    // epsilon scaling
    double maxc = 0;
    for (int i = 0; i < n*n; i++) if (cost[i] > maxc) maxc = cost[i];
    double eps = maxc / 4.0; // initial epsilon
    if (eps < 1e-9) eps = 1e-9;

    while (eps > 1e-12) {
        // auction phase with current epsilon
        // repeat until all assigned
        int unassigned = n;
        // queue of unassigned persons
        int* queue = malloc(n * sizeof(int));
        for (int i = 0; i < n; i++) queue[i] = i;
        int qhead = 0;
        while (qhead < n) {
            int i = queue[qhead++];
            // find best and second best
            double best = INFINITY, second = INFINITY;
            int bestj = -1;
            for (int j = 0; j < n; j++) {
                double v = cost[i*n + j] + price[j];
                if (v < best) { second = best; best = v; bestj = j; }
                else if (v < second) { second = v; }
            }
            // bid
            double bid = (second - best) + eps;
            price[bestj] += bid;
            int prev = owner[bestj];
            owner[bestj] = i;
            if (prev >= 0) {
                queue[qhead++] = prev; // re-add to queue
            }
        }
        free(queue);
        eps *= 0.25;
    }
    // extract assignment
    for (int j = 0; j < n; j++) assign[owner[j]] = j;
    free(price); free(owner);
}
```

