#include <stdlib.h>
#include <float.h>

void lapjv(int n, const double* cost, int* x) {
    int i, j, k, i1, j1, j2, numfree, last, low, up, f;
    double min, umin, usubmin, v2, h;
    int* y = malloc(n * sizeof(int));
    int* free_rows = malloc(n * sizeof(int));
    int* pred = malloc(n * sizeof(int));
    int* colList = malloc(n * sizeof(int));
    double* d = malloc(n * sizeof(double));
    double* v = malloc(n * sizeof(double));
    double* u = malloc(n * sizeof(double));

    for (j = 0; j < n; j++) {
        v[j] = cost[j];
        for (i = 1; i < n; i++) {
            if (cost[i*n + j] < v[j]) v[j] = cost[i*n + j];
        }
    }

    for (i = 0; i < n; i++) { x[i] = -1; y[i] = -1; }
    numfree = 0;
    for (i = 0; i < n; i++) {
        umin = cost[i*n] - v[0];
        j1 = 0;
        usubmin = DBL_MAX;
        for (j = 1; j < n; j++) {
            h = cost[i*n + j] - v[j];
            if (h < usubmin) {
                if (h < umin) { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                else { usubmin = h; j2 = j; }
            }
        }
        i1 = y[j1];
        if (i1 == -1) {
            y[j1] = i; x[i] = j1;
        } else {
            y[j1] = i; x[i] = j1; x[i1] = -1;
            free_rows[numfree++] = i1;
        }
        u[i] = umin;
    }

    for (int loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0;
        int prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free_rows[k++];
            umin = cost[i*n] - v[0];
            j1 = 0;
            usubmin = DBL_MAX;
            for (j = 1; j < n; j++) {
                h = cost[i*n + j] - v[j];
                if (h < usubmin) {
                    if (h < umin) { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                    else { usubmin = h; j2 = j; }
                }
            }
            i1 = y[j1];
            v2 = usubmin - umin;
            if (v2 < 1e-15) v2 = 1e-15;
            u[i] = umin;
            if (i1 == -1) {
                y[j1] = i; x[i] = j1;
            } else {
                v[j1] -= v2;
                u[i1] += v2;
                y[j1] = i; x[i] = j1; x[i1] = -1;
                free_rows[numfree++] = i1;
            }
        }
    }

    for (f = 0; f < numfree; f++) {
        i = free_rows[f];
        for (j = 0; j < n; j++) {
            d[j] = cost[i*n + j] - v[j];
            pred[j] = i;
            colList[j] = j;
        }
        low = 0; up = 0;
        j1 = -1;
        while (1) {
            if (low == up) {
                last = low;
                min = d[colList[low]];
                for (k = low + 1; k < n; k++) {
                    j = colList[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) { min = h; up = low; }
                        colList[k] = colList[up];
                        colList[up++] = j;
                    }
                }
                for (k = low; k < up; k++) {
                    j = colList[k];
                    if (y[j] == -1) { j1 = j; goto augment; }
                }
            }
            j1 = colList[low++];
            i1 = y[j1];
            h = cost[i1*n + j1] - v[j1] - min;
            for (k = up; k < n; k++) {
                j = colList[k];
                v2 = cost[i1*n + j] - v[j] - h;
                if (v2 < d[j]) {
                    pred[j] = i1;
                    if (v2 == min) {
                        if (y[j] == -1) { j1 = j; goto augment; }
                        colList[k] = colList[up];
                        colList[up++] = j;
                    }
                    d[j] = v2;
                }
            }
        }
    augment:
        while (1) {
            i1 = pred[j1];
            y[j1] = i1;
            k = j1;
            j1 = x[i1];
            x[i1] = k;
            if (i1 == i) break;
        }
    }

    free(y); free(free_rows); free(pred); free(colList); free(d); free(v); free(u);
}
