    collist = new col_t[dim];
    matches = new col_t[dim];
    d = new cost_t[dim];
    pred = new row_t[dim];

    /* init how many times a row has been assigned in column reduction */
    for (i = 0; i < dim; i++) {
        matches[i] = 0;
    }

    /* COLUMN REDUCTION */
    for (j = dim-1; j >= 0; j--) {  /* reverse order gives better results */
        /* find minimum cost over rows */
        min = assigncost[0][j];
        imin = 0;
        for (i = 1; i < dim; i++) {
            if (assigncost[i][j] < min) {
                min = assigncost[i][j];
                imin = i;
            }
        }
        v[j] = min;
        if (++matches[imin] == 1) {
            /* init assignment if minimum row assigned for first time */
            rowsol[imin] = j;
            colsol[j] = imin;
        } else if (v[j] < v[rowsol[imin]]) {
            /* if more than one column has minimum, assign the one with smaller v */
            j1 = rowsol[imin];
            rowsol[imin] = j;
            colsol[j] = imin;
            colsol[j1] = -1;
        } else {
            colsol[j] = -1;
        }
    }

    /* REDUCTION TRANSFER */
    for (i = 0; i < dim; i++) {
        if (matches[i] == 0) {  /* fill list of unassigned rows */
            free[numfree++] = i;
        } else if (matches[i] == 1) {  /* transfer reduction from rows that are assigned once */
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < dim; j++) {
                if (j != j1) {
                    if (assigncost[i][j] - v[j] < min) {
                        min = assigncost[i][j] - v[j];
                    }
                }
            }
            v[j1] = v[j1] - min;
        }
    }

    /* AUGMENTING ROW REDUCTION */
    for (loopcnt = 0; loopcnt < 2; loopcnt++) {  /* repeat once */
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k++];
            /* find minimum and second minimum reduced cost over columns */
            umin = assigncost[i][0] - v[0];
            j1 = 0;
            usubmin = BIG;
            for (j = 1; j < dim; j++) {
                h = assigncost[i][j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) {
                /* change the reduction of the minimum column to increase the minimum reduced cost in the row to the subminimum */
                v[j1] = v[j1] - (usubmin - umin);
            } else {  /* minimum and subminimum equal */
                if (i0 >= 0) {  /* minimum column j1 is assigned */
                    /* swap columns j1 and j2, as j2 may be unassigned */
                    j1 = j2;
                    i0 = colsol[j2];
                }
            }
            /* (re-)assign i to j1, possibly de-assigning an i0 */
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {  /* minimum column j1 assigned earlier */
                if (umin < usubmin) {
                    /* put in current k, and go back to that k */
                    free[--k] = i0;
                } else {
                    /* no further reduction possible */
                    free[numfree++] = i0;
                }
            }
        }
    }

    /* AUGMENT SOLUTION for each free row */
    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        /* Dijkstra shortest augmenting path algorithm */
        for (j = 0; j < dim; j++) {
            d[j] = assigncost[freerow][j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
