                last = low - 1;
                /* scan columns for ... */
                min = d[collist[up]];
                up++;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) {
                            up = low;
                            min = h;
                        }
                        /* new index belongs to last column */
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                /* check if any of the minimum columns happens to be unassigned */
                for (k = low; k < up; k++) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassignedfound = TRUE;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                /* update d for all columns not yet scanned */
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = assigncost[i][j1] - v[j1] - min;
                for (k = up; k < dim; k++) {
                    j = collist[k];
