        for (int j = 0; j < n; j++) {
            double v = row[j] + price[j];
            if (v < best) { second = best; best = v; bestj = j; }
            else if (v < second) second = v;
        }
        double bid = (second - best) + eps;
        price[bestj] += bid;
        int prev = owner[bestj];
        owner[bestj] = i;
        rowcol[i] = bestj;
        if (prev >= 0) stack[count++] = prev;
    }

    eps *= scale;
    while (eps > eps_final) {
        // Parallel happiness check
        #pragma omp parallel for schedule(static)
        for (int i = 0; i < n; i++) {
            int j = rowcol[i];
            const double* row = cost + (size_t)i * n;
            double best = DBL_MAX;
            for (int jj = 0; jj < n; jj++) {
                double v = row[jj] + price[jj];
                if (v < best) best = v;
            }
            unhappy[i] = (row[j] + price[j] > best + eps) ? 1 : 0;
        }
        // Sequential re-bid of unhappy rows
        count = 0;
        for (int i = 0; i < n; i++) {
            if (unhappy[i]) {
                // free old column
                int jold = rowcol[i];
                if (jold >= 0) owner[jold] = -1;
                rowcol[i] = -1;
                stack[count++] = i;
